        S.cfg_set("fs_Ly_spans", [float(y) for y in Ly_calc])

        # ── 🏛️ RECTANGULAR COLUMNS DESIGN FROM FLAT SLAB LOADS ─────────────────────
        from modules.columns import design_rectangular_column

        col_sf = S.cfg_val("col_Safety_Factor", 1.20)
