                rb_m_b2 = rb_models_d.get("B2", {})
                rb_m_b3 = rb_models_d.get("B3", {})
                rb_m_cb1 = rb_models_d.get("CB1", {})

                rb_b1_calc = float(rb_m_b1.get("t_env_calc", 60.0))
